using System; using System.Collections.Generic; using Crownfall.Stats;
namespace Crownfall.Artifacts { [Serializable] public sealed class ArtifactInstance { public ArtifactDefinition Definition; public int Level=1; public void Upgrade(){if(Level<3)Level++;} } public sealed class ArtifactSystem { public const int MaxSlots=3; readonly List<ArtifactInstance> slots=new List<ArtifactInstance>(); public IReadOnlyList<ArtifactInstance> Slots=>slots; public bool TryAcquire(ArtifactDefinition d){var same=slots.Find(x=>x.Definition==d);if(same!=null){if(same.Level>=3)return false;same.Upgrade();return true;}if(slots.Count>=MaxSlots)return false;slots.Add(new ArtifactInstance{Definition=d});return true;} public void ApplyStatic(StatModifierSet stats,string unitKey){foreach(var a in slots){if(a.Definition.kind==ArtifactKind.WarDrum){float[] v={0,.08f,.14f,.20f};stats.AddOrReplace(new StatModifier{Id="artifact_war_drum",Source="artifact:"+unitKey,Stat=StatType.AttackSpeed,Operation=ModifierOperation.AdditivePercent,Value=v[a.Level]});}}} public int StartingEnergyBonus(){int n=0;foreach(var a in slots)if(a.Definition.kind==ArtifactKind.ArcaneCrown)n=new[]{0,10,20,30}[a.Level];return n;} public float KillHealFraction(){float n=0;foreach(var a in slots)if(a.Definition.kind==ArtifactKind.BloodChalice)n=new[]{0f,.03f,.05f,.07f}[a.Level];return n;} } }
